function roleT(role) { return T('role_' + role); }
function holderT(role, r) { return role === 'teacher' ? T('role_teacher') + ' (' + esc(USERS[r.owner].name) + ')' : roleT(role); }
function holderTxt(role, r) { return role === 'teacher' ? t('role_teacher') + ' (' + USERS[r.owner].name + ')' : t('role_' + role); }
function pending(r) { var c = r.custody[r.custody.length - 1]; return c && !c.by ? c : null; }
function lastMove(r) { var x = r.created; r.log.forEach(function (l) { x = Math.max(x, l.at); }); r.custody.forEach(function (c) { x = Math.max(x, c.at, c.byAt || 0); }); return x; }
function waitDays(r) { return Math.max(0, Math.floor((Math.max(NOW, Date.now()) - lastMove(r)) / DAY)); }
