    var lcl = i === 0 ? 'transparent' : (k !== 'fut' ? 'linear-gradient(90deg,' + mixc(cp, c) + ',' + c + ')' : 'var(--future)');
    var lcr = i === n - 1 ? (r.status === 'done' ? c : 'var(--future)') : (litN ? 'linear-gradient(90deg,' + c + ',' + mixc(c, cn) + ')' : 'var(--future)');
