/* ===== รายจ่ายประจำ: each kind has its own memo in the finance book ===== */
var RECUR_KIND = { 'ค่าจ้างครูอัตราจ้าง ครูต่างชาติ และลูกจ้างชั่วคราว': 'wage', 'เงินสมทบประกันสังคม': 'sso', 'ค่าไฟฟ้า': 'elec', 'ค่าน้ำประปา': 'water', 'ค่าโทรศัพท์': 'phone', 'ค่าเก็บขยะ': 'trash' };
