  var cr = c.getBoundingClientRect(), wide = window.innerWidth >= 900, root = c.querySelector('.ftroot'); if (!root) return;
  var rel = function (e) { var r = e.getBoundingClientRect(); return { l: r.left - cr.left, r: r.right - cr.left, t: r.top - cr.top, b: r.bottom - cr.top, cx: r.left - cr.left + r.width / 2, cy: r.top - cr.top + r.height / 2 }; };
  var R0 = rel(root), d = '', defs = {}, grads = '';
  var mark = function (col) { defs[col] = 1; return 'url(#ftmk' + col.slice(1) + ')'; };
  var plain = function (p, col, w) { return '<path d="' + p + '" fill="none" stroke="' + col + '" stroke-width="' + (w || 4) + '" stroke-linecap="round" stroke-linejoin="round" marker-end="' + mark(col) + '"/>'; };
